PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schools (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,short_name TEXT,motto TEXT,app_name TEXT NOT NULL DEFAULT 'School Attendance App',logo_url TEXT,primary_color TEXT NOT NULL DEFAULT '#008759',secondary_color TEXT NOT NULL DEFAULT '#075f45',accent_color TEXT NOT NULL DEFAULT '#16a873',background_color TEXT NOT NULL DEFAULT '#f5f7f8',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,school_id INTEGER NOT NULL,full_name TEXT NOT NULL,username TEXT NOT NULL,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('SUPER_ADMIN','SCHOOL_ADMIN','SECTION_HEAD','TEACHER')),active INTEGER NOT NULL DEFAULT 1,force_password_change INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (school_id) REFERENCES schools(id),UNIQUE(school_id,username));
CREATE TABLE IF NOT EXISTS sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,school_id INTEGER NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id),FOREIGN KEY (school_id) REFERENCES schools(id));
CREATE TABLE IF NOT EXISTS grades (id INTEGER PRIMARY KEY AUTOINCREMENT,school_id INTEGER NOT NULL,name TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY (school_id) REFERENCES schools(id),UNIQUE(school_id,name));
CREATE TABLE IF NOT EXISTS classes (id INTEGER PRIMARY KEY AUTOINCREMENT,school_id INTEGER NOT NULL,grade_id INTEGER NOT NULL,name TEXT NOT NULL,display_name TEXT NOT NULL,academic_year TEXT,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY (school_id) REFERENCES schools(id),FOREIGN KEY (grade_id) REFERENCES grades(id),UNIQUE(school_id,display_name,academic_year));
CREATE TABLE IF NOT EXISTS students (id INTEGER PRIMARY KEY AUTOINCREMENT,school_id INTEGER NOT NULL,admission_number TEXT NOT NULL,full_name TEXT NOT NULL,grade_id INTEGER NOT NULL,class_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (school_id) REFERENCES schools(id),FOREIGN KEY (grade_id) REFERENCES grades(id),FOREIGN KEY (class_id) REFERENCES classes(id),UNIQUE(school_id,admission_number));
CREATE TABLE IF NOT EXISTS teacher_class_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT,school_id INTEGER NOT NULL,teacher_id INTEGER NOT NULL,class_id INTEGER NOT NULL,FOREIGN KEY (school_id) REFERENCES schools(id),FOREIGN KEY (teacher_id) REFERENCES users(id),FOREIGN KEY (class_id) REFERENCES classes(id),UNIQUE(school_id,teacher_id,class_id));
CREATE TABLE IF NOT EXISTS attendance_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,school_id INTEGER NOT NULL,class_id INTEGER NOT NULL,date TEXT NOT NULL,submitted_by INTEGER NOT NULL,submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (school_id) REFERENCES schools(id),FOREIGN KEY (class_id) REFERENCES classes(id),FOREIGN KEY (submitted_by) REFERENCES users(id),UNIQUE(school_id,class_id,date));
CREATE TABLE IF NOT EXISTS attendance_records (id INTEGER PRIMARY KEY AUTOINCREMENT,school_id INTEGER NOT NULL,session_id INTEGER NOT NULL,student_id INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('PRESENT','ABSENT')),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (school_id) REFERENCES schools(id),FOREIGN KEY (session_id) REFERENCES attendance_sessions(id),FOREIGN KEY (student_id) REFERENCES students(id),UNIQUE(session_id,student_id));
CREATE TABLE IF NOT EXISTS attendance_changes (id INTEGER PRIMARY KEY AUTOINCREMENT,school_id INTEGER NOT NULL,record_id INTEGER NOT NULL,old_status TEXT NOT NULL,new_status TEXT NOT NULL,changed_by INTEGER NOT NULL,reason TEXT,changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (school_id) REFERENCES schools(id),FOREIGN KEY (record_id) REFERENCES attendance_records(id),FOREIGN KEY (changed_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS teacher_period_attendance (id INTEGER PRIMARY KEY AUTOINCREMENT,school_id INTEGER NOT NULL,class_id INTEGER NOT NULL,date TEXT NOT NULL,period INTEGER NOT NULL,status TEXT NOT NULL,submitted_by INTEGER NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (school_id) REFERENCES schools(id),FOREIGN KEY (class_id) REFERENCES classes(id),FOREIGN KEY (submitted_by) REFERENCES users(id),UNIQUE(school_id,class_id,date,period));
CREATE TABLE IF NOT EXISTS school_settings (school_id INTEGER PRIMARY KEY,academic_year TEXT,period_count INTEGER NOT NULL DEFAULT 8,allow_attendance_edit INTEGER NOT NULL DEFAULT 1,submission_deadline TEXT,teacher_statuses TEXT NOT NULL DEFAULT '["ARRIVED","DELAYED","RELIEF","NO TEACHER PRESENTED"]',FOREIGN KEY (school_id) REFERENCES schools(id));
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,school_id INTEGER NOT NULL,user_id INTEGER,action TEXT NOT NULL,target_type TEXT,target_id TEXT,old_values TEXT,new_values TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (school_id) REFERENCES schools(id),FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_users_school ON users(school_id);
CREATE INDEX IF NOT EXISTS idx_students_school_class ON students(school_id,class_id);
CREATE INDEX IF NOT EXISTS idx_attendance_school_date ON attendance_sessions(school_id,date);
CREATE INDEX IF NOT EXISTS idx_records_session ON attendance_records(session_id);
